public class Main {
    static long ways(int n) {
        if (n <= 2) {
            return n;
        }
        long prev = 1, current = 2;
        for (int i = 3; i <= n; i++) {
            long next = prev + current;
            prev = current;
            current = next;
        }
        return current;
    }

    public static void main(String[] args) {
        System.out.println(ways(5));
        System.out.println(ways(45));
    }
}
